BASE_COUNTS={'nightingale_dagger':12,'victor_spear':14,'thunder_axe':24,'pool_spear':14}
def load(name):return json.loads((MODELS/(name+'.json')).read_text(encoding='utf-8'))
def check():
 for name,parts in ADDITIONS.items():
  data=load(name);actual=data['elements']
  assert len(actual)==BASE_COUNTS[name]+len(parts),(name,len(actual))
  assert actual[-len(parts):]==parts,name+' P41 overlay missing or drifted'
  assert len({json.dumps(e,sort_keys=True) for e in actual})==len(actual),name+' duplicate cuboids'
 root=load('noon_sickle');held=load('noon_sickle_held');icon=load('noon_sickle_icon')
 assert root['loader']=='neoforge:separate_transforms'
 assert root['base']['parent']=='slavicmyths:item/noon_sickle_held'
 assert root['perspectives']['gui']['parent']=='slavicmyths:item/noon_sickle_icon'
 assert icon['textures']['layer0']=='slavicmyths:item/noon_sickle'
 assert len(held['elements'])==12
 print('PASS P41: 5 actual weapon models, additive canonical overlay, old GUI/FP/TP unchanged, runtime NOT_RUN')
def apply():
 for name,parts in ADDITIONS.items():
  path=MODELS/(name+'.json');data=load(name);elements=data['elements']
  # Only historical baseline (without overlay) or exact P41 layer is supported;
  # never silently rebase a different owner's geometry.
  if len(elements)==BASE_COUNTS[name]:
   elements.extend(parts)
   path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
  else:
   assert elements[-len(parts):]==parts and len(elements)==BASE_COUNTS[name]+len(parts),name+' unknown version'
 check()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--apply',action='store_true');o=a.parse_args()
 if o.apply:apply()
 else:check()
